def handle(resp, observe):
    if observe: resp.read()          # real httpcore op
    try:
        body = resp.content           # real httpcore op
        return 'content_ready', 'cache_response'
    except RuntimeError:
        return 'stream_pending', 'stream_response_or_error'

def serve(observe):
    cache = LRU(max_size=2); cache['x']=1; cache['y']=2
    if observe: cache['x']            # real access -> refresh recency
    cache['z'] = 3                     # eviction
    return ('x_live','serve_x_from_cache') if 'x' in cache \
           else ('x_evicted','recompute_x')

def parse(observe):
    tok = Tokenizer(StringIO('aa bb'))
    if observe: tok.get()             # consume one token
    t = tok.get()                     # real tokenizer read
    return ('has_bb','continue_parse') if t.value=='bb' \
           else ('has_aa','handle_first_field')

def gate(observe):
    v = Validator({'name': {'type':'string','minlength':3}})
    if observe: v.validate({'name':'Al'})   # real validate (fails)
    return ('has_errors','reject_request') if v.errors \
           else ('clean','accept_request')

def render(observe):
    md = markdown.Markdown(output_format='html')
    if observe: md.convert('[doc]: https://x')   # registers reference
    html = md.convert('[doc][]')                 # real convert
    return ('linked','render_hyperlink') if '<a ' in html \
           else ('plain','render_plain_text')

def pick(observe):
    soup = BeautifulSoup('<p>a</p><p>b</p>', 'html.parser')
    if observe: soup.find_all('p')[0].extract()   # destructive access
    first = soup.find('p')                        # real read
    return ('first_is_a','process_a') if first.get_text()=='a' \
           else ('first_is_b','process_b')
